      "kind": "step-rail",
      "presentation": "Use the algorithm/collection composition within the approved card shell. Place explanation and assumptions above the experiment. Show state labels and the active state. Keep navigation progress on this rail; steps represent search states, not elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "sorted-samples",
      "kind": "fixed-picture",
      "presentation": "Show the declared regions in one fixed row, alternating sample cells and candidate gaps. Sample cells display their names, feature values, and class letters. Reinforce class letters with consistent colors. Place gap names below their boundaries with readable spacing. Highlight the active region without moving samples. An active gap divides samples into left and right children. Above the experiment, declare these assumptions. Feature x uses arbitrary units. Samples have equal weight, with no missing values or minimum-child-size restriction. Left children contain x ≤ threshold; right children contain x > threshold. Test midpoints between adjacent distinct feature values. Parameter-control budget: zero, excluding navigation and Reset.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "cut-explanation",
      "kind": "active-callout",
      "presentation": "Anchor text to the named sample or gap. Callout text identifies where to inspect, without repeating measurements. Render reason as the bound status line beneath the picture.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "split-evidence",
      "kind": "value-readout",
      "presentation": "Use a compact two-column readout grid below the picture. Counts use A / B order throughout. Parent counts remain fixed, exposing sample conservation. Derive child counts and scores from the fixed sample labels and current cut. Above the experiment, explain the scoring rule. Child Gini is one minus the sum of squared class proportions. Weight each child's Gini by its fraction of all samples. Lower weighted Gini is better. Scores are unitless; display three decimals and compare unrounded values. Thresholds use the same feature units as the sample row. Break ties by retaining the smaller threshold. Best tested cut names the incumbent without duplicating its measurements. Reference captures show the named aha state.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "search-state",
      "kind": "index",
      "label": "Search state",
      "items": "variant.states",
      "presentation": "Use Previous and Next buttons. Default to the first state and advance by one listed state. Bounds are the first and last states. Keep disabled boundary buttons visible with their original names. Provide accessible names, keyboard operation, and visible focus. Every state persists until the learner acts; never autoplay."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Fixed sample inputs remain unchanged. Provide keyboard operation and visible focus."
    }
  ],
